package org.dromara.sports.tables.d13.change_case;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.dromara.sports.platform.core.*;
import org.springframework.stereotype.Service;
import java.util.*;
import static org.dromara.sports.platform.core.BusinessSupport.*;

/** The existing manager remains responsible until the nominated roster member personally accepts. */
@Service @RequiredArgsConstructor
public class EntryHandoverService implements CapabilityProvider {
    private final ScopedJdbc db;private final ObjectMapper json;
    private static final Set<String> READS=Set.of("asp_change_case","asp_registration","asp_registration_member","asp_account","asp_profile_display","asp_team_room","asp_team_room_member");
    private static final Set<String> WRITES=Set.of("asp_change_case","asp_registration","asp_team_room","asp_notification");
    public List<CapabilityDefinition> capabilities(){return List.of(
        capability(json,"registration.handover","发起报名管理责任交接","asp_change_case",false,true,Set.of("platform"),"",READS,WRITES,"registrationId","targetAccountId","reason","expectedVersion"),
        capability(json,"registration.acceptHandover","本人接受报名管理责任","asp_change_case",false,true,Set.of("platform"),"",READS,WRITES,"caseId"));}
    public JsonNode preview(String code,JsonNode in){return in.has("registrationId")?detail(id(in,"registrationId")):pending();}
    public JsonNode execute(String code,JsonNode in){long a=account();if(code.equals("registration.handover")){long registration=id(in,"registrationId"),target=id(in,"targetAccountId");db.lock("entry-handover:"+registration);var r=owned(registration,a);if(number(r.get("version"))!=in.path("expectedVersion").asLong(-1))throw fail("报名已变化，请重新核对",409);if(target==a||db.count("SELECT count(*) FROM asp_registration_member m JOIN asp_account a ON a.id=m.account_id WHERE m.registration_id=? AND m.account_id=? AND m.status='confirmed' AND a.status='active'",registration,target)==0)throw fail("请选择另一名已确认参赛的有效成员",409);if(db.count("SELECT count(*) FROM asp_change_case WHERE object_type='registration_manager' AND object_id=? AND status='reviewing' AND (after_snapshot->>'expiresAt')::timestamptz>CURRENT_TIMESTAMP",registration)>0)throw fail("已有管理责任交接待本人接受",409);long caseId=nextId();var before=json.createObjectNode();before.put("managerAccountId",Long.toString(a));before.put("registrationVersion",number(r.get("version")));var after=json.createObjectNode();after.put("managerAccountId",Long.toString(target));after.put("expiresAt",java.time.OffsetDateTime.now().plusHours(24).toString());db.update("INSERT INTO asp_change_case(id,tenant_id,object_type,object_id,before_snapshot,after_snapshot,impact,status,reason) VALUES (?,?,'registration_manager',?,?::jsonb,?::jsonb,'{\"responsibility\":\"registration-and-existing-funds\"}'::jsonb,'reviewing',?)",caseId,r.get("tenant_id"),registration,before.toString(),after.toString(),text(in,"reason",2000));notify(r,target,"报名管理责任待你确认",caseId);return reference(json,"caseId",caseId,"reviewing");}
        long caseId=id(in,"caseId");var c=db.one("SELECT *,before_snapshot::text AS before_json,after_snapshot::text AS after_json FROM asp_change_case WHERE id=? AND object_type='registration_manager'",caseId);if(c==null)throw fail("交接不存在",404);long registration=number(c.get("object_id"));db.lock("entry-handover:"+registration);c=db.one("SELECT *,before_snapshot::text AS before_json,after_snapshot::text AS after_json FROM asp_change_case WHERE id=? AND object_type='registration_manager' FOR UPDATE",caseId);JsonNode before=parse(c.get("before_json")),after=parse(c.get("after_json"));if(id(after,"managerAccountId")!=a)throw fail("请由指定接任成员本人确认",403);if(!"reviewing".equals(c.get("status"))||!java.time.OffsetDateTime.parse(after.path("expiresAt").asText()).isAfter(java.time.OffsetDateTime.now()))throw fail("交接已结束或过期，请原管理人重新发起",409);long previous=id(before,"managerAccountId");var r=owned(registration,previous);if(db.count("SELECT count(*) FROM asp_registration_member m JOIN asp_account a ON a.id=m.account_id AND a.status='active' WHERE m.registration_id=? AND m.account_id=? AND m.status='confirmed'",registration,a)==0)throw fail("你已不在本场已确认名单，暂不能接任",409);int changed=db.update("UPDATE asp_registration SET manager_account_id=?,version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=? AND manager_account_id=? AND version=?",a,registration,previous,before.path("registrationVersion").asInt(-1));if(changed!=1)throw fail("报名责任或状态已经变化，请重新发起交接",409);db.update("UPDATE asp_change_case SET status='completed',version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",caseId);db.update("UPDATE asp_team_room SET host_account_id=?,version=version+1,update_time=CURRENT_TIMESTAMP WHERE registration_id=? AND EXISTS(SELECT 1 FROM asp_team_room_member m WHERE m.room_id=asp_team_room.id AND m.account_id=? AND m.status='active')",a,registration,a);notify(r,previous,"报名管理责任已完成交接",caseId);return reference(json,"registrationId",registration,"handed_over");
    }
    private Map<String,Object> owned(long registration,long a){var r=db.one("SELECT id,tenant_id,manager_account_id,version FROM asp_registration WHERE id=? AND manager_account_id=?",registration,a);if(r==null)throw fail("只有当前报名管理人可以办理交接",403);return r;}
    public JsonNode detail(long registration){long a=account();var r=owned(registration,a);var out=json.createObjectNode();out.set("registration",safeJson(json,r));out.set("candidates",safeJson(json,db.list("SELECT m.account_id,COALESCE(d.nickname,'球友') AS nickname FROM asp_registration_member m JOIN asp_account a ON a.id=m.account_id LEFT JOIN asp_profile_display d ON d.account_id=m.account_id WHERE m.registration_id=? AND m.account_id<>? AND m.status='confirmed' AND a.status='active'",registration,a)));return out;}
    public JsonNode pending(){long a=account();return safeJson(json,db.list("SELECT id,object_id AS registration_id,reason,after_snapshot->>'expiresAt' AS expires_at FROM asp_change_case WHERE object_type='registration_manager' AND status='reviewing' AND after_snapshot->>'managerAccountId'=? AND (after_snapshot->>'expiresAt')::timestamptz>CURRENT_TIMESTAMP ORDER BY create_time",Long.toString(a)));}
    private JsonNode parse(Object value){try{return json.readTree(value.toString());}catch(Exception e){throw new IllegalStateException("Invalid handover record");}}
    private void notify(Map<String,Object> r,long target,String title,long caseId){var content=json.createObjectNode();content.put("title",title);content.put("body","交接包括继续办理报名、历史资金核对和问题收尾，请本人查看并接受。");content.put("target","/portal/registration");db.update("INSERT INTO asp_notification(id,tenant_id,recipient_account_id,business_type,business_id,business_revision,purpose,content,dedupe_key) VALUES (?,?,?,'entry-handover',?,0,'responsibility',?::jsonb,?)",nextId(),r.get("tenant_id"),target,caseId,content.toString(),"handover:"+caseId+":"+title);}
}
